<?php
requireAdmin();$error='';$message='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['planning_action']??'';
 if($action==='persona'){$persona=(string)($_POST['persona']??'');if($persona!==''&&!isset(journeyPersonas()[$persona]))throw new DomainException('INVALID_INPUT');$_SESSION['journey_demo']=$persona;header('Location: /day-plan/?lang=he&switch_lang=1');exit;}
 elseif($action==='invite'){$member=socialQuery("SELECT id FROM members WHERE handle=? AND state='active'",[(string)$_POST['handle']])->fetchColumn();if(!$member)throw new DomainException('לא נמצא משתמש פעיל');$on=($_POST['value']??'')==='on'?'on':'off';socialQuery('INSERT INTO network_settings VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',['journey_invite_'.$member,$on]);$message='הרשאת הפיילוט עודכנה';}
 elseif($action==='walking'){$walking=journeyWalking((string)$_POST['from'],(string)$_POST['to']);$message='תוצאת ספק: '.json_encode($walking,JSON_UNESCAPED_UNICODE);}
 elseif($action==='fact'){$f=json_decode((string)$_POST['document'],true,32,JSON_THROW_ON_ERROR);$v=journeyFactWrite((string)$_POST['subject'],(string)$_POST['type'],$f,(int)$_POST['expected_version'],(string)$_POST['reason']);$message='נשמרה גרסת עובדה '.$v;}
 elseif($action==='flag'){if(!in_array($_POST['feature']??'',['planning','replanning'],true)||!in_array($_POST['value']??'',['internal','pilot','off'],true))throw new DomainException('INVALID_INPUT');socialQuery('INSERT INTO network_settings VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',['journey_'.$_POST['feature'],$_POST['value']]);$message='מצב היכולת עודכן';}
 elseif($action==='decision'){
  journeyModerate((string)$_POST['kind'],(string)$_POST['target'],(string)$_POST['decision'],socialString($_POST['reason']??'',1000,10),(int)($_POST['revision']??0),(int)($_POST['fact_version']??0));$message='החלטה נשמרה ביומן';
 }else throw new DomainException('INVALID_INPUT');
}}catch(Throwable $e){$error=$e->getMessage();http_response_code(422);}
$title='ניהול תכנון ומידע';ob_start();?><section class="page-heading"><h1><?=e($title)?></h1><p>פיילוט טביליסי. עובדות מקור נשמרות בניהול בלבד; שינוי עובדה אינו משנה מסלולים פרטיים.</p><a class="button" href="/day-plan/?lang=he&switch_lang=1">פתיחת מסך התכנון</a> <a class="button secondary" href="/KNISA/planning/?demo=1">פיילוט הדגמה</a></section>
<?php if($error):?><p class="notice error"><?=e($error)?></p><?php endif;if($message):?><p class="notice"><?=e($message)?></p><?php endif?>
<?php if(isset($_GET['demo'])):require ROOT.'/views/journey-demo.php';endif?>
<section class="form-panel"><h2>הפעלה מדורגת</h2><form method="post"><?=csrf()?><input type="hidden" name="planning_action" value="flag"><label>יכולת<select name="feature"><option value="planning">תכנון</option><option value="replanning">שינוי המשך היום</option></select></label><label>מצב<select name="value"><option value="internal">ניהול פנימי בלבד</option><option value="pilot">משתתפים שהוזמנו בלבד</option><option value="off">כבוי — שמירות קיימות נשארות</option></select></label><button>עדכון</button></form></section>
<section class="form-panel"><h2>הזמנת משתתף קיים לפיילוט</h2><form method="post"><?=csrf()?><input type="hidden" name="planning_action" value="invite"><label>שם משתמש ציבורי<input name="handle" required maxlength="30"></label><label>גישה<select name="value"><option value="on">הזמנה</option><option value="off">ביטול גישה לפיילוט</option></select></label><button>שמירה</button></form><p>ההזמנה פועלת רק כשהיכולת במצב משתתפים מוזמנים. היא אינה מקנה הרשאות ניהול.</p></section><section class="form-panel"><h2>מקומות קנוניים בטביליסי</h2><p>מזהה המקור והקישורים הקיימים נשמרים. לא הוזנו שעות או מחירים משוערים כעובדות.</p><ul><?php foreach(tripCatalog() as $x)if($x['city']==='Tbilisi'):$pid=journeyPlace($x['id']);?><li><?=e($x['title'])?> · <code><?=e($pid)?></code> · <?=e($x['id'])?></li><?php endif?></ul></section>
<section class="form-panel"><h2>בדיקת מקטע הליכה</h2><p>נדרשים מפתח פרטי וכניסות מאומתות. התוצאה אינה מפרסמת אוטומטית עובדה.</p><form method="post"><?=csrf()?><input type="hidden" name="planning_action" value="walking"><label>מזהה מקום מוצא<input name="from" required></label><label>מזהה מקום יעד<input name="to" required></label><button>בדיקה אצל ספק ההליכה</button></form></section><section class="form-panel"><h2>גרסת עובדה מאומתת</h2><p>לעובדת הליכה: subject הוא leg:מזהה-מוצא&gt;מזהה-יעד. חובה לתעד מקור, זמן תצפית, זמן בדיקה ותוקף. אין להעתיק את מועד הייבוא למועד התצפית.</p><form method="post"><?=csrf()?><input type="hidden" name="planning_action" value="fact"><label>מזהה נושא<input name="subject" required maxlength="140"></label><label>סוג<select name="type"><?php foreach(['price','hours','operating','accessibility','entrance','leg','duration'] as $type):?><option><?=e($type)?></option><?php endforeach?></select></label><label>גרסה קודמת (0 לחדשה)<input type="number" name="expected_version" value="0" min="0"></label><label>עובדה ומקור JSON<textarea name="document" rows="12" required></textarea></label><label>נימוק בדיקה<textarea name="reason" required minlength="10" maxlength="1000"></textarea></label><button>שמירת גרסה וביטול תוקף הצעות קודמות</button></form></section>
<?php foreach(['report'=>'journey_reports','review'=>'journey_reviews'] as $kind=>$table):?><section class="form-panel"><h2><?=e($kind==='report'?'דיווחי שינוי ממתינים':'משוב ביקור ממתין')?></h2><?php foreach(jq("SELECT * FROM $table WHERE state='pending' ORDER BY ".($kind==='report'?"CASE type WHEN 'closed' THEN 0 WHEN 'access' THEN 1 ELSE 2 END,created":"id").' LIMIT 100') as $row):?><article><?php if($kind==='review'):$row['appeal']=jq("SELECT reason,decision,created FROM journey_decisions WHERE kind='review_appeal' AND target=? ORDER BY id DESC LIMIT 1",[$row['id']])->fetch();$row['review_text']=jq('SELECT locale,body,actual_minutes,actual_cost_minor FROM journey_review_versions WHERE review=? AND revision=?',[$row['id'],$row['revision']])->fetch();endif?><pre><?=e(json_encode($row,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre><form method="post"><?=csrf()?><input type="hidden" name="planning_action" value="decision"><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="target" value="<?=e($row['id'])?>"><input type="hidden" name="revision" value="<?=(int)($row['revision']??0)?>"><?php if($kind==='report'):?><label>גרסת עובדה מאומתת לאישור<input name="fact_version" type="number" min="0" value="0"></label><?php endif?><label>החלטה<select name="decision"><option value="approved">אישור (לדיווח: נדרשת עובדה מאומתת)</option><option value="rejected">דחייה / סגירת דיווח עם נימוק</option><option value="blocked">חסימה</option></select></label><label>נימוק<textarea name="reason" required minlength="10"></textarea></label><button>שמירה</button></form></article><?php endforeach?></section><?php endforeach?>
<section class="form-panel"><h2>מדדי תפעול בפועל</h2><p>אין כאן נתוני הצלחה ממטיילים אמיתיים. אירוע התחלה הוא דיווח עצמי בלבד.</p><ul><?php foreach(jq('SELECT event,status,COUNT(*) n FROM journey_events GROUP BY event,status') as $row):?><li><?=e($row['event'].' · '.$row['status'].' · '.$row['n'])?></li><?php endforeach?></ul><p>דיווחים ממתינים: <?=jq("SELECT COUNT(*) FROM journey_reports WHERE state='pending'")->fetchColumn()?> · גרסאות שהושפעו משינוי עובדה: <?=jq('SELECT COUNT(*) FROM journey_impacts')->fetchColumn()?></p></section>
